(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.018+t*0.3)*18+Math.cos(y*0.013-t*0.22)*12+Math.sin((x+y)*0.008+t*0.15)*8;
  const w1y = Math.cos(y*0.02-t*0.28)*18+Math.sin(x*0.016+t*0.33)*12+Math.cos((x-y)*0.009-t*0.18)*8;
  const sx = x+w1x, sy = y+w1y;
  const w2x = Math.sin(sx*0.012-t*0.4)*10+Math.cos(sy*0.009+t*0.35)*7;
  const w2y = Math.cos(sy*0.014+t*0.38)*10+Math.sin(sx*0.011-t*0.42)*7;
  const px = sx+w2x, py = sy+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0, 1.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7, 0.9],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3, 1.1],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5, 0.85],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6, 1.05],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9, 0.95],
    [80+Math.sin(t*0.45+3)*70, 40+Math.cos(t*0.65+1)*50, 0.11, 2.1, 0.88],
    [400+Math.cos(t*0.55+2)*60, 220+Math.sin(t*0.75+4)*40, 0.085, 1.8, 1.08]
  ];
  let aS=0, iS=0, cS=0, fS=0;
  for (const [sX,sY,f,sp,w] of src) {
    const d = Math.sqrt((px-sX)**2+(py-sY)**2);
    aS += Math.sin(d*f-t*sp)*w;
    iS += Math.sin(d*f*0.7+t*sp*0.6+1.5)*w;
    cS += Math.sin(d*f*1.3-t*sp*0.4+3.0)*w*0.5;
    fS += Math.cos(d*f*0.5+t*sp*0.8-2.0)*w*0.4;
  }
  const n=8; const act=aS/n, inh=iS/n, cor=cS/n, fed=fS/n;
  const bg1 = (Math.sin(px*0.04+py*0.025+t*0.8)+Math.sin(px*0.03-py*0.04+t*1.1))/2;
  const bg2 = Math.sin((px+py)*0.12+t*2.5)*0.2+Math.sin((px-py)*0.1-t*2)*0.2;
  const bg3 = Math.sin(px*0.07-t*1.5)*Math.cos(py*0.06+t*1.3)*0.15;
  const bg = bg1+bg2+bg3;
  const dist=Math.sqrt((px-cx)**2+(py-cy)**2), ang=Math.atan2(py-cy,px-cx);
  const sp1 = Math.sin(dist*0.05-ang*3-t*1.5);
  const sp2 = Math.sin(dist*0.04+ang*4-t*1.2);
  const sp3 = Math.sin(dist*0.03-ang*5+t*0.8)*0.3;
  const spiral = (sp1+sp2)*0.4+sp3;
  const rip = Math.sin(dist*0.08-t*3)*Math.exp(-dist*0.005)*0.4;
  const rd1 = Math.tanh((act-inh*0.7+bg*0.3+spiral)*2.2);
  const rd2 = Math.tanh((cor*1.5-fed+bg*0.2+rip)*1.8);
  const rdMix = rd1*0.7+rd2*0.3;
  const cell = Math.tanh((Math.sin(px*0.15)*Math.sin(py*0.15)+Math.sin((px+py)*0.1+t)*0.5)*1.5)*0.3;
  const voro = (Math.sin(px*0.2+Math.floor(py*0.2)*3.7+t*0.5)+Math.sin(py*0.2+Math.floor(px*0.2)*2.3-t*0.4))*0.12;
  const blend = rdMix*0.65+cell*0.2+voro*0.15;
  const v = blend*0.5+0.5;
  const pal = [
    [5,12,52],[10,45,95],[12,85,120],[18,130,135],
    [180,175,60],[210,130,55],[185,70,60],[120,35,65],
    [60,18,55],[15,25,70],[5,12,52]
  ];
  const idx=v*(pal.length-1), i=Math.min(idx|0,pal.length-2), f=idx-i;
  const lum=0.82+Math.sin(rdMix*Math.PI)*0.18;
  const edge=Math.abs(rdMix)>0.65?1.12:Math.abs(rd2)>0.5?1.06:1.0;
  const depth=1.0+rd2*0.08;
  return [
    Math.min(255,Math.max(0,(pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge*depth))|0,
    Math.min(255,Math.max(0,(pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge*depth))|0,
    Math.min(255,Math.max(0,(pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge*depth))|0
  ];
}
